/bin/bash -lc "cat > /tmp/folio-browser/check.mjs <<'JS'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1080}, deviceScaleFactor:1});
const errors=[];
page.on('pageerror',error=>errors.push(error.message));
await page.goto('http://localhost:5175/');
await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'/tmp/folio-desktop.png',fullPage:true});
const editor=page.getByRole('textbox',{name:'Текст публикации в Markdown'});
const preview=page.getByRole('region',{name:'Предпросмотр Markdown'});
await editor.fill('## Проверка\\n\\n**Жирный** и *курсив*\\n\\n- первый\\n- второй\\n\\n> цитата\\n\\n[ссылка](https://example.com)\\n\\n"'`const x = 1`'"\\n\\n- [x] Готово\\n\\n| А | Б |\\n|---|---|\\n| 1 | 2 |');
await page.waitForTimeout(100);
assert.equal(await preview.locator('h2').innerText(),'Проверка');
assert.equal(await preview.locator('strong').innerText(),'Жирный');
assert.equal(await preview.locator('em').innerText(),'курсив');
assert.equal(await preview.locator('blockquote').innerText(),'цитата');
assert.equal(await preview.locator('table').count(),1);
assert.equal(await preview.getByRole('checkbox').isChecked(),true);
await editor.fill('Привет');
await editor.evaluate(el=>el.setSelectionRange(0,6));
await page.getByRole('button',{name:'Жирный (Ctrl+B)',exact:true}).click();
assert.equal(await editor.inputValue(),'**Привет**');
assert.equal(await preview.locator('strong').innerText(),'Привет');
await page.getByRole('button',{name:'Просмотр',exact:true}).click();
assert.equal(await editor.isVisible(),false);
await page.getByRole('button',{name:'Разделить',exact:true}).click();
await page.getByRole('button',{name:'Шпаргалка по Markdown'}).click();
await page.getByRole('heading',{name:'Знакомьтесь, Markdown.'}).waitFor();
await page.getByRole('button',{name:'Всё понятно, пишем"'!'"'}).click();
await page.getByRole('button',{name:'Развернуть редактор',exact:true}).click();
assert.equal(await page.locator('.editor-expanded').count(),1);
await page.keyboard.press('Escape');
assert.equal(await page.locator('.editor-expanded').count(),0);
await page.getByRole('button',{name:'Сохранить черновик',exact:true}).click();
await page.getByRole('status').waitFor();
await page.reload();
assert.equal(await editor.inputValue(),'**Привет**');
await page.getByRole('button',{name:'Черновики',exact:true}).click();
assert.equal(await page.locator('.draft-card').count(),1);
await page.locator('.draft-card').click();
await editor.fill('<script>window.pwned=true</script>\\n\\n[опасно](javascript:alert(1))');
assert.equal(await preview.locator('script').count(),0);
assert.equal(await page.evaluate(()=>window.pwned),undefined);
assert.notEqual(await preview.locator('a').getAttribute('href'),'javascript:alert(1)');
await editor.fill('');
await page.getByRole('button',{name:'Просмотр',exact:true}).click();
await page.getByRole('button',{name:'Сохранить черновик',exact:true}).click();
await page.getByRole('alert').waitFor();
assert.equal(await editor.isVisible(),true);
await page.evaluate(()=>localStorage.clear());
await page.reload();
for (const width of [390,768,1024,1440]) {
  await page.setViewportSize({width,height:900});
  const dimensions=await page.evaluate(()=>({scroll:document.documentElement.scrollWidth,window:innerWidth}));
  assert.ok(dimensions.scroll<=dimensions.window,"'`Overflow at ${width}: ${dimensions.scroll}`);
}
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'"'/tmp/folio-mobile.png',fullPage:true});
assert.deepEqual(errors,[]);
console.log('PASS: live Markdown, GFM, formatting, modes, help, fullscreen, persistence, draft navigation, XSS handling, validation, responsive widths.');
await browser.close();
JS"

